#[inline] pub fn to_zigzag(v: i64) -> u64 {
    if v >= 0 { (v as u64) << 1 } else { ((!v as u64) << 1) | 1 }
}
#[inline] pub fn from_zigzag(v: u64) -> i64 {
    if v & 1 == 0 { (v >> 1) as i64 } else { !((v >> 1) as i64) }
}
#[inline] pub fn to_negative_zigzag(v: u64) -> u64 {
    if v == 0 { 0 } else { (v - 1) << 1 | 1 }
}

