// ── LEB128 ────────────────────────────────────────────────────────────────────

pub fn leb_length(value: u64) -> usize {
    // ceil(bit_len / 7), clamped to >= 1 (value 0 → 1). Branchless: `.max(1)`
    // subsumes the value==0 case, and there is no separate `% 7`.
    (((64 - value.leading_zeros()) + 6) / 7).max(1) as usize
}

pub fn read_leb(data: &[u8], at: usize) -> Result<(u64, usize), DagrError> {
    let mut result = 0u64;
    let mut shift = 0usize;
    let mut pos = at;
    loop {
        let b = *data.get(pos).ok_or(DagrError::InvalidData)?;
        // A u64 needs at most 10 LEB bytes (shift 63). Anything longer is malformed
        // input, not a value — reject instead of shifting past the width (which panics
        // in debug builds and silently wraps in release).
        if shift > 63 { return Err(DagrError::InvalidData); }
        result |= ((b & 0x7F) as u64) << shift;
        pos += 1; shift += 7;
        if b >> 7 == 0 { break; }
    }
    Ok((result, pos - at))
}

