// ── VTable read helper ────────────────────────────────────────────────────────
// Returns Vec of field offsets (as absolute positions from start of data slice).
// Missing fields are None. Node start = vtable_start (passed in from read_leb caller).

/// Zero-heap view over a node's vtable. Resolves slots on demand by reinterpreting the
/// 1- or 2-byte slot entries in place — no `Vec`, no allocation. This is the hot read
/// path: constructing a `VtableView` only parses the (LEB) header; individual field
/// offsets are resolved lazily via `slot()`, so a reader that touches 2 of N fields pays
/// for 2 slot reads, not N.
///
/// `len()` is the number of slots ACTUALLY present in the buffer (clamped to what is
/// fully in-bounds). A buffer written by an OLDER schema with fewer fields — or one that
/// is truncated — simply yields `None` for the trailing slots instead of erroring, which
/// is what makes higher-index reads forward-compatible.
#[derive(Clone, Copy)]
pub struct VtableView<'a> {
    data: &'a [u8],
    base: usize,       // slot values are byte offsets relative to this cursor
    slot_start: usize, // first slot byte
    count: usize,      // # of fully-in-bounds slots (may be < the writer's field count)
    is16: bool,        // 2-byte slots vs 1-byte
}

impl<'a> VtableView<'a> {
    /// Parse the vtable header at `vtable_start`. Returns `None` only if the HEADER
    /// (not the slots) is out of bounds or malformed. Never allocates.
    ///
    /// Output layout: `[count_leb][slots][header] [node_data...]`; `vtable_start` points
    /// at the header byte. Slot values encode the distance from the cursor-before-vtable
    /// to each field cursor; `base = vtable_start + b1` is that reference point.
    #[inline]
    fn parse(data: &'a [u8], vtable_start: usize) -> Option<Self> {
        let (hdr, b1) = try_read_leb(data, vtable_start)?;
        let vt_start = if hdr & 1 == 0 {
            // Dedup reference: hdr is (cursor_before_this - vtcursor_cached) as even zigzag;
            // the cached count_leb sits `from_zigzag(hdr)` bytes forward from base.
            let delta = from_zigzag(hdr);
            (vtable_start + b1).checked_add_signed(delta as isize)?
        } else {
            // Fresh vtable: hdr = to_negative_zigzag(sz); count_leb is `sz` bytes BEFORE header.
            let sz = (-(from_zigzag(hdr))) as usize;
            vtable_start.checked_sub(sz)?
        };
        let (vt_size, b2) = try_read_leb(data, vt_start)?;
        let claimed = (vt_size >> 1) as usize;
        let is16 = vt_size & 1 != 0;
        let slot_start = vt_start + b2;
        let slot_bytes = if is16 { 2 } else { 1 };
        // Clamp to the slots that are fully readable — truncated- and older-schema-safe.
        let count = claimed.min(data.len().saturating_sub(slot_start) / slot_bytes);
        Some(Self { data, base: vtable_start + b1, slot_start, count, is16 })
    }

    /// Number of slots present. May be less than a newer reader's expected field count
    /// when the buffer was written by an older schema (or is truncated).
    #[inline]
    pub fn len(&self) -> usize { self.count }
    #[inline]
    pub fn is_empty(&self) -> bool { self.count == 0 }

    /// Resolve field slot `i` to an absolute byte offset, or `None` if the field is
    /// absent (slot value 0) or beyond the stored slots (older/shorter vtable). Reads a
    /// single 1- or 2-byte entry in place — no allocation.
    #[inline]
    pub fn slot(&self, i: usize) -> Option<usize> {
        if i >= self.count { return None; }
        let v = if self.is16 {
            let p = self.slot_start + i * 2;
            u16::from_le_bytes([*self.data.get(p)?, *self.data.get(p + 1)?]) as usize
        } else {
            *self.data.get(self.slot_start + i)? as usize
        };
        if v == 0 { None } else { Some(self.base + v - 1) }
    }
}

/// Strict vtable read for the eager restore path: errors if the header is malformed.
/// Returns a zero-heap `VtableView`; resolve fields with `.slot(i)`.
#[inline]
pub fn read_vtable(data: &[u8], vtable_start: usize) -> Result<VtableView<'_>, DagrError> {
    VtableView::parse(data, vtable_start).ok_or(DagrError::InvalidData)
}

