// ── f16 / bf16 conversion helpers ────────────────────────────────────────────

pub fn f16_bits_to_f32(bits: u16) -> f32 {
    let sign: u32 = (bits as u32 >> 15) << 31;
    let exp16 = ((bits >> 10) & 0x1F) as i32;
    let mant16 = (bits & 0x3FF) as u32;
    let bits32 = if exp16 == 0 {
        if mant16 == 0 { sign } else {
            let mut m = mant16; let mut e = -14 + 127;
            while m & 0x400 == 0 { m <<= 1; e -= 1; }
            sign | ((e as u32) << 23) | ((m & 0x3FF) << 13)
        }
    } else if exp16 == 31 { sign | 0x7F800000 | (mant16 << 13)
    } else                 { sign | (((exp16 + 112) as u32) << 23) | (mant16 << 13) };
    f32::from_bits(bits32)
}

pub fn read_f16(data: &[u8], at: usize) -> Result<f32, DagrError> {
    Ok(f16_bits_to_f32(read_u16(data, at)?))
}

pub fn bf16_bits_to_f32(bits: u16) -> f32 {
    f32::from_bits((bits as u32) << 16)
}

pub fn read_bf16(data: &[u8], at: usize) -> Result<f32, DagrError> {
    Ok(bf16_bits_to_f32(read_u16(data, at)?))
}

// ── Packed float compressibility checks (pure, no writes) ─────────────────────

pub fn can_pack_f32(v: f32) -> bool {
    if v.is_nan() || v.is_infinite() || v == 0.0_f32 { return true; }
    let iv = v as i64;
    if iv as f32 == v && iv.unsigned_abs() < (1 << 21) && leb_length(to_zigzag(iv)) <= 3 { return true; }
    f16_bits_to_f32(f32_to_f16_bits_lossy(v)) == v
}

pub fn can_pack_f64(v: f64) -> bool {
    if v.is_nan() || v.is_infinite() || v == 0.0_f64 { return true; }
    let iv = v as i64;
    if iv as f64 == v && iv.unsigned_abs() < (1_u64 << 48) && leb_length(to_zigzag(iv)) <= 7 { return true; }
    (v as f32) as f64 == v  // fits in f32 (5 bytes packed < 9 bytes raw)
}

// ── Packed float decode (frozen-packed ebs=0 path) ────────────────────────────

pub fn read_packed_f32(data: &[u8], at: usize) -> Result<(f32, usize), DagrError> {
    let tag = *data.get(at).ok_or(DagrError::InvalidData)?;
    match tag {
        0x00 => Ok(( 0.0_f32, 1)),
        0x01 => Ok((-0.0_f32, 1)),
        0x02 => Ok(( f32::INFINITY, 1)),
        0x03 => Ok((-f32::INFINITY, 1)),
        0x04 => Ok(( f32::NAN, 1)),
        0x05 => { let (zz, lb) = read_leb(data, at + 1)?; Ok((from_zigzag(zz) as f32, 1 + lb)) }
        0x06 => { let b16 = read_u16(data, at + 1)?; Ok((f16_bits_to_f32(b16), 3)) }
        0x07 => Ok((read_f32(data, at + 1)?, 5)),
        _ => Ok((0.0_f32, 1)),
    }
}

pub fn read_packed_f64(data: &[u8], at: usize) -> Result<(f64, usize), DagrError> {
    let tag = *data.get(at).ok_or(DagrError::InvalidData)?;
    match tag {
        0x00 => Ok(( 0.0_f64, 1)),
        0x01 => Ok((-0.0_f64, 1)),
        0x02 => Ok(( f64::INFINITY, 1)),
        0x03 => Ok((-f64::INFINITY, 1)),
        0x04 => Ok(( f64::NAN, 1)),
        0x05 => { let (zz, lb) = read_leb(data, at + 1)?; Ok((from_zigzag(zz) as f64, 1 + lb)) }
        0x06 => { let b16 = read_u16(data, at + 1)?; Ok((f16_bits_to_f32(b16) as f64, 3)) }
        0x07 => { let f32v = read_f32(data, at + 1)?; Ok((f32v as f64, 5)) }
        0x08 => Ok((read_f64(data, at + 1)?, 9)),
        _ => Ok((0.0_f64, 1)),
    }
}

// f16/bf16 packed ebs=0 path: only 1-byte special-value tags are possible
