            fn next(&mut self)->Option<Self::Item>{ if self.idx>=self.len{return None;} self.idx+=1;
                match pk_slice_at(self.data,self.pos){Ok((s,adv))=>{self.pos+=adv;Some($conv(s))}Err(e)=>{self.idx=self.len;Some(Err(e))}} }
