// ── Vtable (regular-node) array accessors — INDEXABLE + iterable, zero-alloc ──
// Vtable arrays are fixed-width, so unlike packed arrays they support O(1) `get(i)` as well as
// iteration. Element families:
//   fixed numeric : required [count][elem·sz];  optional [count][nil-bitset][elem·sz]
//                   (nil slots STILL occupy sz bytes — not compacted). f16/bf16 read → f32.
//   bool          : required [count][value-bitset]; optional [count][nil-bitset][value-bitset
//                   COMPACTED (one bit per non-nil)] — get(i) popcounts the nil prefix.
//   utf8/data     : V62 slot table [hdr=(count<<2)|wc][count slots·es][payloads]; each slot is a
//                   rel-offset to a [len][bytes] record. Borrowed &str / &[u8] (no String/Vec).
#[inline] pub fn vt_str_at(data: &[u8], at: usize) -> Result<&str, DagrError> { let (s, _) = pk_slice_at(data, at)?; pk_str_from(s) }
#[inline] pub fn vt_bytes_at(data: &[u8], at: usize) -> Result<&[u8], DagrError> { let (s, _) = pk_slice_at(data, at)?; Ok(s) }

